arguments.command:
cd /workspace && python3 - <<'PYEOF'
p='src/image.cpp'
s=open(p).read()
s=s.replace("""static bool fail_at(int line) {
    if (std::getenv("SCAMP_DEBUG")) fprintf(stderr, "image validate failed at line %d\\n", line);
    return false;
}""","""static bool fail_at(int line) {
    if (std::getenv("SCAMP_DEBUG")) fprintf(stderr, "image validate failed at line %d\\n", line);
    return false;
}

static int fail_node(int line) {
    if (std::getenv("SCAMP_DEBUG")) fprintf(stderr, "image validate failed at line %d\\n", line);
    return -1;
}""")
# the visit function returns an int node index
s=s.replace("""    bool visit(int stage, uint32_t cell, int parent, int parent_stage,
               int origin, int G, uint64_t reg_hi, uint64_t reg_lo, bool bulk_slot);""","""    int visit(int stage, uint32_t cell, int parent, int parent_stage,
              int origin, int G, uint64_t reg_hi, uint64_t reg_lo, bool bulk_slot);""")
s=s.replace("""bool Validator::visit(int stage, uint32_t cell, int parent, int parent_stage,
                      int origin, int G, uint64_t reg_hi, uint64_t reg_lo, bool bulk_slot) {""","""int Validator::visit(int stage, uint32_t cell, int parent, int parent_stage,
                     int origin, int G, uint64_t reg_hi, uint64_t reg_lo, bool bulk_slot) {""")
# inside visit, failures must return -1
import re
start = s.index("int Validator::visit(")
end = s.index("bool Validator::validate(")
body = s[start:end]
body = body.replace("return fail_at(__LINE__);","return fail_node(__LINE__);")
s = s[:start] + body + s[end:]
open(p,'w').write(s)
PYEOF
grep -n "fail_node\|fail_at" src/image.cpp | head -40 && python3 build.py 2>&1|tail -2
